// Целеустремлённый Охотник (корбук, Мастер Казней): «Психопатия» на Тяжести 0, и Тяжесть не может опуститься ниже 0.
// Повторный запуск расстройство не дублирует — только подтягивает нижний предел (sheets/tabs/disorders.mjs).
const res = await grantStartingDisorder(actor, item, { name: "Психопатия", severityMin: 0, incurable: true, label: "Целеустремлённый Охотник" });
if (!res.ok) ui.notifications?.info(res.reason);
